/**
 * Test flow for getAttachmentsOnRecord action
 * Demonstrates getting attachments from a record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testGetAttachmentsOnRecord = Flow(
    {
        $id: Now.ID['test_get_attachments_on_record_flow'],
        name: 'Test Get Attachments On Record',
        description: 'Tests the getAttachmentsOnRecord core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_get_attachments_on_record_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.getAttachmentsOnRecord,
            { $id: Now.ID['test_get_attachments_on_record_action'] },
            {
                source_record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_get_attachments_on_record_log'] },
            {
                log_level: 'info',
                log_message: `getAttachmentsOnRecord outputs: parameter=${wfa.dataPill(result.parameter, 'string')}, parameter1=${wfa.dataPill(result.parameter1, 'string')}`,
            }
        )
    }
)
